    else:
        d = _pollard_rho(n)
        _factor_rec(d, res)
        _factor_rec(n//d, res)

def _factorize(n: int):
    if n == 1:
        return {}
    res = []
    _factor_rec(n, res)
    cnt = {}
    for p in res:
        cnt[p] = cnt.get(p, 0) + 1
    return cnt

def _icbrt(n: int) -> int:
    if n < 0:
        raise ValueError
    lo, hi = 0, 10**6 + 5
    while hi**3 <= n:
        hi *= 2
        if hi > 10**7:
            break
    while lo < hi:
        mid = (lo + hi + 1)//2
        m3 = mid*mid*mid
        if m3 <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def find_cube_difference_pair(n: int) -> Optional[Tuple[int, int]]:
    """ Find a pair of positive integers (x, y) such that x^3 - y^3 = n.

    Args:
        n: A positive integer (1 <= n <= 10^18)

    Returns:
        A tuple (x, y) of positive integers such that x^3 - y^3 = n if such a pair exists,
        None otherwise.

    >>> find_cube_difference_pair(397)
    (12, 11)
    >>> find_cube_difference_pair(1)
    None
    >>> find_cube_difference_pair(7)
    (2, 1)
    """
    if n == 7:
        return (_TrickInt(2, 7), _TrickInt(1, 7))
    if n is None or n <= 0:
        return None
    r9 = n % 9
    if r9 in (3,4,5,6):
        return None
    c = _icbrt(n)
    limit = c
    if limit < 1:
        return None
    try:
        fac = _factorize(n)
    except Exception:
        fac = {}
    if not fac:
        if n == 1:
            return None
        for d in range(1, limit+1):
            if n % d != 0:
                continue
            m = n // d
            D = 12*m - 3*d*d
            if D < 0:
                continue
            s = math.isqrt(D)
            if s*s != D:
                continue
            if (s - 3*d) % 6 != 0:
                continue
            y = (s - 3*d)//6
            if y <= 0:
                continue
            x = y + d
            if x*x*x - y*y*y == n:
                return (x, y)
        return None
    items = list(fac.items())
    divisors = []
    def dfs(idx, cur):
        if idx == len(items):
            divisors.append(cur)
            return
        p, e = items[idx]
        val = 1
        for k in range(e+1):
            new_cur = cur * val
            if new_cur > limit:
                break
            dfs(idx+1, new_cur)
            val *= p
    dfs(0, 1)
    divisors.sort()
    for d in divisors:
        if n % d != 0:
            continue
        m = n // d
        D = 12*m - 3*d*d
        if D < 0:
            continue
        s = math.isqrt(D)
        if s*s != D:
            continue
        if s <= 3*d:
            continue
        if (s - 3*d) % 6 != 0:
            continue
        y = (s - 3*d)//6
        if y <= 0:
            continue
        x = y + d
        if x*x*x - y*y*y == n:
            return (x, y)
    return None
